import { useState, type KeyboardEvent } from 'react';
import { Stack, Field, Input, Tag, Text } from '@jinx-ui/react';

type TagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

export default function TagPicker({
  label = 'Теги',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');

  const commit = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const tag = draft.trim();
    if (!tag) return;
    if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
      setDraft('');
      return;
    }
    commit([...tags, tag]);
    setDraft('');
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((existing) => existing !== tag));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <Field label={label}>
        <Input
          value={draft}
          placeholder={placeholder}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={addTag}
        />
      </Field>

      {tags.length > 0 ? (
        <Stack direction="row" gap="var(--jx-space-1)" wrap>
          {tags.map((tag) => (
            <Tag
              key={tag}
              onRemove={() => removeTag(tag)}
              removeLabel={`Удалить тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text tone="muted" size="sm">
          Теги пока не выбраны
        </Text>
      )}
    </Stack>
  );
}

